function validate([length, updates]) {
  if (!Number.isInteger(length) || length < 1 || length > 100000) return 'length is between 1 and 100000.';
  if (!Array.isArray(updates) || updates.length > 10000) return 'updates holds at most 10000 triples.';
  for (const update of updates) {
    if (!Array.isArray(update) || update.length !== 3 || !update.every(Number.isInteger)) return 'Each update is [startIdx, endIdx, inc] of integers.';
    const [start, end, inc] = update;
    if (start < 0 || start > end || end >= length) return 'Each update needs 0 <= startIdx <= endIdx < length.';
    if (inc < -1000 || inc > 1000) return 'Each inc is between -1000 and 1000.';
  }
  return null;
}

