function getModifiedArray(length, updates) {
  const diff = new Array(length + 1).fill(0);

  for (const [start, end, inc] of updates) {
    diff[start] += inc;
    diff[end + 1] -= inc;
  }

  const result = new Array(length);
  let running = 0;
  for (let i = 0; i < length; i++) {
    running += diff[i];
    result[i] = running;
  }
  return result;
}

