function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const length = size === 'large' ? int(1500, 2000) : int(1, 8);
  const count = size === 'large' ? int(1500, 2000) : int(0, 5);
  const updates = [];
  for (let u = 0; u < count; u++) {
    const a = int(0, length - 1);
    const b = int(0, length - 1);
    const inc = size === 'large' ? int(-1000, 1000) : (rand() < 0.15 ? (rand() < 0.5 ? -1000 : 1000) : int(-5, 5));
    updates.push([Math.min(a, b), Math.max(a, b), inc]);
  }
  return [length, updates];
}
